-- GENERATED by apps/hackernews/bundle.py from tools/gamekit/gamekit.lua, src/hn.lua and src/lock/lock.lua -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

local N = (function()
-- Hacker News pieces that need no screen: the addresses of the two public APIs, HN's comment
-- HTML as plain text, ages and domains, and word wrap that also breaks words too long for a line
-- (addresses).
--
-- A list is HN's own ranking (Firebase: topstories.json ... a few KB of ids), its stories' titles
-- and counts come 24 at a time from one Algolia search for exactly those ids (tags
-- "(story_1,story_2,...)", about 7 KB). A story and each comment come from Firebase's item/<id>.json,
-- whose "kids" are the replies in HN's order.

local N = {}

N.FIREBASE = 'https://hacker-news.firebaseio.com/v0/'
N.ALGOLIA = 'https://hn.algolia.com/api/v1/'
N.PER_PAGE = 24
local FIELDS = '&attributesToRetrieve=title,url,points,num_comments,author,created_at_i&attributesToHighlight=%5B%5D'
N.LISTS = { top = 'topstories', new = 'newstories', best = 'beststories', ask = 'askstories', show = 'showstories' }

-- percent-encoding without %w (which follows the C locale and may take bytes of UTF-8 letters)
function N.enc(s)
  return (tostring(s):gsub('[^A-Za-z0-9%-%._~]', function(c) return string.format('%%%02X', c:byte()) end))
end

function N.ids_url(tab) return N.FIREBASE .. N.LISTS[tab] .. '.json' end
function N.item_url(id) return N.FIREBASE .. 'item/' .. id .. '.json' end
-- the stories with these ids, in any order
function N.stories_url(ids)
  local tags = {}
  for k, id in ipairs(ids) do tags[k] = 'story_' .. id end
  return N.ALGOLIA .. 'search?tags=' .. N.enc('(' .. table.concat(tags, ',') .. ')') .. '&hitsPerPage=' .. #ids .. FIELDS
end
-- a search: stories by relevance, page from 0
function N.search_url(q, page)
  return N.ALGOLIA .. 'search?tags=story&query=' .. N.enc(q) .. '&hitsPerPage=' .. N.PER_PAGE .. '&page=' .. page .. FIELDS
end

-- ids as strings, read from the raw JSON: a list of ids (topstories.json), or an item's "kids"
-- (the reader's Lua may have 32-bit numbers, where a decoded id could come back rounded)
function N.ids(body)
  local t = {}
  for id in tostring(body or ''):gmatch('%d+') do t[#t + 1] = id end
  return t
end
function N.kids(body)
  return N.ids(tostring(body or ''):match('"kids"%s*:%s*%[([%d,%s]*)%]'))
end

-- an Algolia hit -> a story row
function N.story(h)
  return { id = tostring(h.objectID), title = tostring(h.title or '(untitled)'), url = h.url and tostring(h.url) or nil,
           points = tonumber(h.points) or 0, comments = tonumber(h.num_comments) or 0,
           by = tostring(h.author or ''), time = tonumber(h.created_at_i) or 0 }
end
-- one list row as a line of text, and back (list_<tab>.txt keeps the last list for opening offline)
function N.row_text(s)
  return table.concat({ s.id, (s.title:gsub('[\t\n]', ' ')), s.url or '', s.points, s.comments, s.by, s.time }, '\t')
end
function N.row_parse(line)
  local id, title, url, points, comments, by, time = line:match('^(%d+)\t([^\t]*)\t([^\t]*)\t(%d*)\t(%d*)\t([^\t]*)\t(%d*)$')
  if not id then return nil end
  return { id = id, title = title, url = url ~= '' and url or nil, points = tonumber(points) or 0,
           comments = tonumber(comments) or 0, by = by, time = tonumber(time) or 0 }
end

function N.domain(url)
  local d = url and url:match('^%a+://([^/:?#]+)')
  return d and (d:gsub('^www%.', '')) or nil
end

------------------------------------------------------------------ For you (1.3.0)
-- foryou.txt, one entry a line: "rust" a topic, "-crypto" a muted word, "-site:medium.com" a
-- muted site. Lower case (ASCII), trimmed, each once.

local function trim(s) return (s:gsub('^%s+', ''):gsub('%s+$', '')) end
-- lower case for A-Z only (string.lower and %w follow the C locale and may change UTF-8 bytes)
local function lower(s) return (s:gsub('[A-Z]', function(c) return string.char(c:byte() + 32) end)) end
local function add_once(list, v)
  for _k, x in ipairs(list) do if x == v then return false end end
  list[#list + 1] = v
  return true
end

function N.foryou_parse(text)
  local fy = { topics = {}, words = {}, sites = {} }
  for line in (tostring(text or '') .. '\n'):gmatch('([^\n]*)\n') do
    local s = lower(trim((line:gsub('\r', ''))))
    local site = s:match('^%-%s*site:%s*(%S+)$')
    if site then add_once(fy.sites, (site:gsub('^www%.', '')))
    elseif s:sub(1, 1) == '-' then
      local w = trim(s:sub(2))
      if w ~= '' then add_once(fy.words, w) end
    elseif s ~= '' then
      add_once(fy.topics, (s:gsub('%s+', ' ')))
    end
  end
  return fy
end

function N.foryou_text(fy)
  local out = {}
  for _k, t in ipairs(fy.topics) do out[#out + 1] = t end
  for _k, w in ipairs(fy.words) do out[#out + 1] = '-' .. w end
  for _k, s in ipairs(fy.sites) do out[#out + 1] = '-site:' .. s end
  return table.concat(out, '\n')
end

-- one search for all the topics: each optional (a story matching more of them ranks higher, then
-- by points), a topic of several words a phrase; the last two days, 10 points or more; 40 a page,
-- so that some are left after the mutes
function N.foryou_url(topics, now, page)
  local q = {}
  for _k, topic in ipairs(topics) do
    local t = topic:gsub('"', '')
    q[#q + 1] = t:find(' ', 1, true) and ('"' .. t .. '"') or t
  end
  local query = N.enc(table.concat(q, ' '))
  return N.ALGOLIA .. 'search?tags=story&query=' .. query .. '&optionalWords=' .. query .. '&advancedSyntax=true'
    .. '&numericFilters=' .. N.enc('created_at_i>' .. ((now or 0) - 172800) .. ',points>=10')
    .. '&hitsPerPage=40&page=' .. (page or 0) .. FIELDS
end

-- the title's words, lower case (letters, digits and the like; whole UTF-8 characters)
local function words_of(title)
  local out = {}
  for w in lower(tostring(title or '')):gmatch("[A-Za-z0-9\128-\255][A-Za-z0-9\128-\255'%+#%.%-]*") do
    out[#out + 1] = (w:gsub("[%.%-']+$", ''))
  end
  return out
end
local function has_words(title_words, phrase)
  local set = {}
  for _k, w in ipairs(title_words) do set[w] = true end
  for w in phrase:gmatch('%S+') do if not set[w] then return false end end
  return true
end

function N.muted(row, fy)
  local tw = words_of(row.title)
  for _k, w in ipairs(fy.words) do if has_words(tw, w) then return true end end
  local d = N.domain(row.url)
  if d then
    d = lower(d)
    for _k, s in ipairs(fy.sites) do
      if d == s or d:sub(-(#s + 1)) == '.' .. s then return true end
    end
  end
  return false
end

function N.topics_in(title, topics)
  local tw, out = words_of(title), {}
  for _k, t in ipairs(topics) do if has_words(tw, t) then out[#out + 1] = t end end
  return out
end

local STOP = {}
for w in ('the and for with from that this what how why who are was were has have had not you your our its'
    .. ' into over about after than then when will can just new now all any via using use one two out'
    .. ' show ask tell more most some his her they them their there here been being but get got')
    :gmatch('%S+') do STOP[w] = true end
-- the words of a title that could be a topic (More like this): 3 letters or more, not a stop word
function N.title_words(title)
  local out = {}
  for _k, w in ipairs(words_of(title)) do
    if #w >= 3 and not STOP[w] and not w:match('^%d+$') then add_once(out, w) end
  end
  return out
end

function N.ago(t, now)
  if not t or t <= 0 or not now or now <= 0 then return '' end
  local s = math.max(0, now - t)
  local function n(d) return math.floor(s / d) end       -- an integer also when t came as a float
  if s < 3600 then return math.max(1, n(60)) .. ' min ago' end
  if s < 86400 then return n(3600) .. ' h ago' end
  if s < 86400 * 365 then return n(86400) .. ' d ago' end
  return n(86400 * 365) .. ' y ago'
end

-- HN's HTML (comments, Ask HN texts): <p> paragraphs, <i>, <a>, <pre><code>, entities
local ENT = { amp = '&', lt = '<', gt = '>', quot = '"', apos = "'", nbsp = ' ', hellip = '...', mdash = '-', ndash = '-' }
local function entity(e)
  local n = e:match('^#[xX](%x+)$')
  n = n and tonumber(n, 16) or tonumber(e:match('^#(%d+)$') or '')
  if n then return (n > 0 and n < 0x110000) and utf8.char(n) or '' end
  return ENT[e] or ('&' .. e .. ';')
end
function N.text(html)
  local s = tostring(html or '')
  s = s:gsub('\r', ''):gsub('<pre><code>(.-)</code></pre>', function(code) return '\n\n' .. code:gsub('\n+$', '') .. '\n\n' end)
  s = s:gsub('<[pP]>', '\n\n'):gsub('<br%s*/?>', '\n'):gsub('<[^>]*>', '')
  s = s:gsub('&(#?%w+);', entity)
  s = s:gsub('\n\n\n+', '\n\n'):gsub('^%s+', ''):gsub('%s+$', '')
  return s
end

-- A story's comments all at once, for the AI (Algolia's search, flat, with their parents): about
-- 35 KB per 100 comments, so a page of `per` stays under the reader's 128 KB an answer.
function N.comments_url(story_id, page, per)
  return N.ALGOLIA .. 'search?tags=comment,story_' .. story_id .. '&hitsPerPage=' .. per .. '&page=' .. page
    .. '&attributesToRetrieve=comment_text,author,parent_id,created_at_i&attributesToHighlight=%5B%5D'
end

local function idstr(v)
  if type(v) == 'number' then return string.format('%d', math.floor(v)) end
  return tostring(v or '')
end

-- a page of Algolia comment hits, kept small: { id, parent, by, t, text } each. The parents are
-- read from the raw JSON in order (a decoded number above 2^24 may come back rounded); objectID
-- is a string already.
function N.comment_hits(d, body)
  local parents = {}
  for p in tostring(body or ''):gmatch('"parent_id"%s*:%s*(%d+)') do parents[#parents + 1] = p end
  local hits = type(d) == 'table' and type(d.hits) == 'table' and d.hits or {}
  local use_raw = #parents == #hits
  local out = {}
  for k, h in ipairs(hits) do
    out[#out + 1] = { id = idstr(h.objectID), parent = use_raw and parents[k] or idstr(h.parent_id), by = tostring(h.author or '?'),
                      t = tonumber(h.created_at_i) or 0, text = N.text(h.comment_text) }
  end
  return out
end

-- The comments as one text for the AI: "author: text", a reply indented two spaces under the
-- comment it answers; the first level in HN's order (order: the story's kids), replies oldest
-- first (HN's own order of replies is not in the data). At most budget bytes, whole comments;
-- returns the text and how many comments it holds.
function N.thread_text(hits, story_id, order, budget)
  local kids, known = {}, {}
  for _k, c in ipairs(hits) do known[c.id] = true end
  for _k, c in ipairs(hits) do
    local p = (c.parent ~= '' and known[c.parent]) and c.parent or tostring(story_id)   -- a lost parent: first level
    kids[p] = kids[p] or {}
    kids[p][#kids[p] + 1] = c
  end
  for _p, list in pairs(kids) do table.sort(list, function(a, b) if a.t ~= b.t then return a.t < b.t end return a.id < b.id end) end
  local rank = {}
  for k, id in ipairs(order or {}) do rank[tostring(id)] = k end
  local top = kids[tostring(story_id)] or {}
  table.sort(top, function(a, b)
    local ra, rb = rank[a.id] or math.huge, rank[b.id] or math.huge
    if ra ~= rb then return ra < rb end
    if a.t ~= b.t then return a.t < b.t end
    return a.id < b.id
  end)
  local out, used, n, full = {}, 0, 0, false
  local function walk(list, depth)
    for _k, c in ipairs(list) do
      if full then return end
      local line = string.rep('  ', depth) .. c.by .. ': ' .. c.text:gsub('%s*\n+%s*', ' ')
      if used + #line + 1 > budget then full = true; return end
      out[#out + 1] = line
      used, n = used + #line + 1, n + 1
      if kids[c.id] then walk(kids[c.id], depth + 1) end
    end
  end
  walk(top, 0)
  if full then out[#out + 1] = '[' .. (#hits - n) .. ' more comments are left out here.]' end
  return table.concat(out, '\n'), n
end

-- the bytes of s that fit in width w (whole UTF-8 characters, at least one)
local function fit(f, s, w)
  local best = nil
  pcall(function()
    for p in utf8.codes(s) do
      if p > 1 then
        if kit.width(f, s:sub(1, p - 1)) > w then break end
        best = p - 1
      end
    end
  end)
  return best or math.max(1, math.min(#s, w // 12))
end

-- word wrap in the given font: lines no wider than w; a word wider than a line is broken
function N.wrap(s, fname, w)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if kit.width(f, cand) <= w then line = cand
      else
        if line ~= '' then out[#out + 1] = line end
        line = word
        while kit.width(f, line) > w do
          local n = fit(f, line, w)
          out[#out + 1] = line:sub(1, n)
          line = line:sub(n + 1)
        end
      end
    end
    out[#out + 1] = line
  end
  return out
end

return N
end)()

-- Hacker News' sleep screen (bundle.py puts tools/gamekit/gamekit.lua as `kit` and src/hn.lua as
-- `N` in front): the For you stories the app saved (list_foryou.txt, fetched at foryou_at.txt),
-- with the time they were fetched. When the interval chosen in the app (settings.txt lockevery,
-- minutes) has passed, the same one search is asked again while locked: API 2.26 (firmware
-- 26111201) gives the lock session ctx.net when the manifest's lockscreen block has "net": true.
-- No topics: nothing to fetch, no connection. The request goes out in on_load; a timer wake holds
-- its frame until the answer, the first session draws at once and again after it.
-- ctx.lock:done() ends the session once nothing is pending. Each session sets the next wake: the
-- interval itself, at most an hour (the reader aligns wakes to it; 3 and 6 hours wake hourly).

local W, H = 480, 800
local MAX_WAKE_S = 3600         -- ctx.lock:set_interval takes 30-3600 s
local SLACK_S = 120             -- a wake may come early (seen: up to a minute)
local pending = false           -- the request out in this session
-- store: cut (the store's API gives a lock screen no network; tools/store_export.py drops this)
local asked = false
local holding = false           -- an early wake waiting for the aligned time it was woken for
-- store: end

local function read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
local function write(name, s) pcall(function() ctx.storage:write(name, s) end) end
local function clock()
  local ok, t = pcall(function() return ctx.clock:now() end)
  return (ok and type(t) == 'table') and t or {}
end
local function now_sec() return math.floor(tonumber(clock().epoch_sec) or 0) end
-- the wall clock's offset from UTC, seconds (whole quarter hours)
local function offset()
  local t = clock()
  if not tonumber(t.hour) then return 0 end
  local wall = t.hour * 3600 + (t.minute or 0) * 60 + (t.second or 0)
  local off = (wall - now_sec() % 86400) % 86400
  if off > 14 * 3600 then off = off - 86400 end
  return math.floor(off / 900 + 0.5) * 900
end

-- when the list was fetched, by the wall clock: "updated 14:05", "updated yesterday 22:10"
local function stamp(at)
  if not at then return nil end
  local off = offset()
  local days = (now_sec() + off) // 86400 - (at + off) // 86400
  local hm = string.format('%02d:%02d', (at + off) % 86400 // 3600, (at + off) % 3600 // 60)
  if days <= 0 then return 'updated ' .. hm end
  return days == 1 and ('updated yesterday ' .. hm) or ('updated ' .. days .. ' days ago')
end

local function saved_rows(fy)
  local rows = {}
  for line in (read('list_foryou.txt') or ''):gmatch('[^\n]+') do
    local r = N.row_parse(line)
    if r and not N.muted(r, fy) then rows[#rows + 1] = r end
  end
  return rows
end

-- store: cut
-- the wake log: one line a session and one an answer, the last 20, in wakes.txt (private storage:
-- XTApps/hackernews/files/ on the card), to see what the sleep screen did while nobody looked
local function wlog(s)
  pcall(function()
    local w = (now_sec() + offset()) % 86400
    local lines = {}
    for l in (read('wakes.txt') or ''):gmatch('[^\n]+') do lines[#lines + 1] = l end
    lines[#lines + 1] = string.format('%02d:%02d:%02d ', w // 3600, w % 3600 // 60, w % 60) .. s
    while #lines > 20 do table.remove(lines, 1) end
    ctx.storage:write('wakes.txt', table.concat(lines, '\n') .. '\n')
  end)
end

-- A timer wake comes up to a minute early; one that ends before the aligned time it was woken for
-- gets a second wake at that time. So an early session holds with ctx:after (it runs in a 2.26
-- lock session and keeps it open) until 2 s past it.
local function hold_if_early()
  if not (ctx.lock and ctx.lock.reason == 'timer') then return end
  local iv = tonumber(ctx.lock.interval_sec) or MAX_WAKE_S
  local rem = (iv - (now_sec() + offset()) % iv) % iv
  if rem == 0 or rem > SLACK_S then return end
  local ok, tm = pcall(function()
    return ctx:after((rem + 2) * 1000, function()
      holding = false
      pcall(function() ctx:invalidate() end)          -- draw again; that draw ends the session
    end)
  end)
  holding = ok and tm ~= nil
end

-- ask Algolia for the For you stories; -> what it did, for the log
local function try_refresh(fy)
  if asked then return 'fetch' end
  if not ctx.net then return 'no network on the lock screen' end
  asked = true
  local ok, job, err = pcall(function()
    return ctx.net:request({ url = N.foryou_url(fy.topics, now_sec(), 0), method = 'GET', timeout_ms = 30000,
                             headers = { ['User-Agent'] = 'XteinkLicoriceHN/1.3' } }, function(c, resp)
      pending = false
      local okw, what = pcall(function()
        if type(resp) ~= 'table' then return 'reply: none' end
        local code = tonumber(resp.status) or tonumber(resp.code)
        if type(resp.body) ~= 'string' or resp.ok == false then return 'reply failed: ' .. tostring(resp.err) end
        if code and code >= 400 then return 'reply HTTP ' .. code end
        local d = ctx.json:decode(resp.body)
        if type(d) ~= 'table' then return 'reply not JSON' end
        local out = {}
        for _k, h in ipairs(d.hits or {}) do out[#out + 1] = N.row_text(N.story(h)) end
        write('list_foryou.txt', table.concat(out, '\n'))
        write('foryou_at.txt', tostring(now_sec()))
        return 'reply ' .. #out .. ' stories'
      end)
      wlog(okw and what or ('reply error: ' .. tostring(what)))
      pcall(function() ctx:invalidate() end)            -- draw again (fresh or not); that draw ends the session
    end)
  end)
  pending = ok and job ~= nil
  if not pending then return 'fetch not sent: ' .. tostring(ok and err or job) end
  return 'fetch'
end
-- store: end

function on_draw(c, gg)
  if not gg then return end
  local ok, err = pcall(function()
    gg:clear(0)
    local t = clock()
    local fy = N.foryou_parse(read('foryou.txt'))
    if tonumber(t.year) then
      local wd = { 'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday' }
      local days = (now_sec() + offset()) // 86400
      gg:text(24, 20, wd[(days + 4) % 7 + 1] .. string.format(', %02d:%02d', t.hour or 0, t.minute or 0), { font = kit.font('medium') })
    end
    gg:text(24, 56, 'Hacker News · For you', { font = kit.font('large') })
    gg:line(24, 100, W - 24, 100)
    gg:line(24, 101, W - 24, 101)
    if #fy.topics == 0 then
      local y = 140
      for _k, l in ipairs(N.wrap('Add topics in the Hacker News app (For you) to see their stories here.', 'medium', W - 48)) do
        gg:text(24, y, l, { font = kit.font('medium') }); y = y + 30
      end
      return
    end
    local rows = saved_rows(fy)
    local y, lh, sh = 116, kit.line_h('medium') + 2, kit.line_h('small') + 2
    for _k, r in ipairs(rows) do
      local tl = N.wrap(r.title, 'medium', W - 48)
      local n = math.min(2, #tl)
      if y + n * lh + sh + 10 > H - 44 then break end
      for i = 1, n do
        local s = tl[i]
        if i == 2 and #tl > 2 then s = kit.short(s, #s - 2) end
        gg:text(24, y, s, { font = kit.font('medium') }); y = y + lh
      end
      local tp = N.topics_in(r.title, fy.topics)
      local m = (#tp > 0 and (table.concat(tp, ', ') .. ' · ') or '') .. r.points .. ' pts · ' .. r.comments .. ' comments'
      local d = N.domain(r.url)
      if d then m = m .. ' · ' .. d end
      gg:text(24, y, kit.short(m, 48), { font = kit.font('small') })
      y = y + sh + 10
      gg:line(24, y - 6, W - 24, y - 6)
    end
    if #rows == 0 then gg:text(24, 140, 'No stories yet for your topics.', { font = kit.font('medium') }) end
    local s = stamp(tonumber(read('foryou_at.txt')))
    if s then gg:text(W - 24 - kit.width(kit.font('small'), s), H - 34, s, { font = kit.font('small') }) end
  end)
  if not ok then pcall(function() gg:text(10, 760, 'lock error: ' .. tostring(err):sub(1, 40)) end) end
  -- store: cut
  if not pending and not holding then pcall(function() ctx.lock:done() end) end   -- 2.26: nothing more to wait for
  -- store: end
end

function on_load()
  -- store: cut
  pcall(function()
    local every = (tonumber((read('settings.txt') or ''):match('lockevery=(%d+)')) or 60) * 60
    local fy = N.foryou_parse(read('foryou.txt'))
    local at = tonumber(read('foryou_at.txt'))
    local did = 'not due'
    if #fy.topics == 0 then did = 'no topics'
    elseif not at or now_sec() - at >= every - SLACK_S then did = try_refresh(fy) end
    hold_if_early()
    if holding then did = did .. '; early: held' end
    local nxt = math.min(every, MAX_WAKE_S)
    pcall(function() ctx.lock:set_interval(nxt) end)
    wlog(string.format('%s lock.net %s every %dm: %s; next %dm', ctx.lock and tostring(ctx.lock.reason) or '?',
      ctx.lock and tostring(ctx.lock.net) or '?', every // 60, did, nxt // 60))
  end)
  -- store: end
end
function on_tick() end
function on_input() return false end
